  const markLock = (id: number, lockedBy: string | null) =>
    queryClient.setQueryData<Claim[]>(claimsKey(sheetId), (old) =>
      old?.map((c) => (c.id === id ? { ...c, lockedBy } : c)),
    );

  const fillForm = (c: Claim) => {
    setEditing(c.id);
    setAmount(c.amount);
